-- Native catalog configuration. Original product/resource UUIDs and historical snapshots remain intact.
CREATE TABLE product_catalogs (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,is_default boolean NOT NULL DEFAULT false,
 name text NOT NULL CHECK(length(name) BETWEEN 2 AND 120 AND name !~ '[[:cntrl:]]'),active boolean NOT NULL DEFAULT true,
 default_language text NOT NULL CHECK(length(default_language)<=40 AND default_language ~ '^[a-z]{2,3}(-[a-z0-9]{2,8}){0,3}$'),
 version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id),CHECK(NOT is_default OR active)
);
CREATE UNIQUE INDEX product_catalog_default ON product_catalogs(tenant_id) WHERE is_default;
CREATE UNIQUE INDEX product_catalog_name ON product_catalogs(tenant_id,lower(name));
CREATE TABLE product_catalog_warehouses(tenant_id uuid NOT NULL,catalog_id uuid NOT NULL,warehouse_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,catalog_id,warehouse_id),FOREIGN KEY(tenant_id,catalog_id) REFERENCES product_catalogs(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id));
CREATE TABLE product_catalog_price_lists(tenant_id uuid NOT NULL,catalog_id uuid NOT NULL,price_list_id uuid NOT NULL,
 PRIMARY KEY(tenant_id,catalog_id,price_list_id),FOREIGN KEY(tenant_id,catalog_id) REFERENCES product_catalogs(tenant_id,id),FOREIGN KEY(tenant_id,price_list_id) REFERENCES price_lists(tenant_id,id));
CREATE TABLE product_catalog_languages(tenant_id uuid NOT NULL,catalog_id uuid NOT NULL,locale text NOT NULL CHECK(length(locale)<=40 AND locale ~ '^[a-z]{2,3}(-[a-z0-9]{2,8}){0,3}$'),
 PRIMARY KEY(tenant_id,catalog_id,locale),FOREIGN KEY(tenant_id,catalog_id) REFERENCES product_catalogs(tenant_id,id));
CREATE TABLE product_catalog_previews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,
 client_key uuid NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL CHECK(scope_hash ~ '^[a-f0-9]{64}$'),request jsonb NOT NULL,payload jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,actor_id,client_key),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id));
CREATE TABLE product_catalog_operations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,preview_id uuid NOT NULL,catalog_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,
 client_key uuid NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),request jsonb NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,preview_id),UNIQUE(tenant_id,actor_id,client_key),FOREIGN KEY(tenant_id,preview_id) REFERENCES product_catalog_previews(tenant_id,id),FOREIGN KEY(tenant_id,catalog_id) REFERENCES product_catalogs(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id));
CREATE TABLE product_catalog_admissions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,operation_id uuid NOT NULL,preview_id uuid NOT NULL,catalog_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,
 txid xid8 NOT NULL DEFAULT pg_current_xact_id(),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,operation_id) REFERENCES product_catalog_operations(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(tenant_id,preview_id) REFERENCES product_catalog_previews(tenant_id,id),FOREIGN KEY(tenant_id,catalog_id) REFERENCES product_catalogs(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id));
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['product_catalogs','product_catalog_warehouses','product_catalog_price_lists','product_catalog_languages','product_catalog_previews','product_catalog_operations','product_catalog_admissions'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tbl);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tbl);
 EXECUTE format('CREATE POLICY tenant ON %I USING (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',tbl);
 EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,dyna_app',tbl);END LOOP;END $$;
CREATE FUNCTION product_catalog_hash(j jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $$ SELECT encode(sha256(convert_to(j::text,'UTF8')),'hex') $$;
CREATE FUNCTION product_catalog_installed() RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT true $$;
CREATE FUNCTION product_catalog_access(uid uuid,kid uuid,writing boolean,pin boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;r text;k public.api_keys;valid boolean:=true;rd boolean:=true;wr boolean:=true;
BEGIN IF pin THEN SELECT role INTO r FROM public.memberships WHERE (tenant_id,user_id)=(t,uid) FOR SHARE;ELSE SELECT role INTO r FROM public.memberships WHERE (tenant_id,user_id)=(t,uid);END IF;
 IF kid IS NOT NULL THEN IF pin THEN SELECT * INTO k FROM public.api_keys WHERE(tenant_id,id,user_id)=(t,kid,uid) FOR SHARE;ELSE SELECT * INTO k FROM public.api_keys WHERE(tenant_id,id,user_id)=(t,kid,uid);END IF;
 valid:=k.id IS NOT NULL AND k.revoked_at IS NULL AND(k.expires_at IS NULL OR k.expires_at>clock_timestamp());rd:=valid AND 'products:read'=ANY(k.scopes);wr:=rd AND 'products:write'=ANY(k.scopes);END IF;
 RETURN jsonb_build_object('role',r,'key_valid',valid,'allowed',coalesce(rd AND r IN('admin','operator','viewer') AND(NOT writing OR(r='admin' AND wr)),false),'can_manage',coalesce(r='admin' AND wr,false));END $$;
CREATE FUNCTION product_catalog_lock() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT pg_advisory_xact_lock(hashtextextended('catalog:'||nullif(current_setting('app.tenant_id',true),''),0)) $$;
CREATE FUNCTION product_catalog_budget(t uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN IF(SELECT count(*) FROM public.product_catalogs WHERE tenant_id=t)>100 OR(SELECT count(*) FROM public.product_catalog_previews WHERE tenant_id=t)>2000 OR(SELECT count(*) FROM public.product_catalog_operations WHERE tenant_id=t)>2000 THEN RAISE EXCEPTION 'Limit historii katalogów' USING ERRCODE='23514';END IF;
 IF coalesce((SELECT sum(pg_column_size(p)) FROM public.product_catalog_previews p WHERE tenant_id=t),0)+coalesce((SELECT sum(pg_column_size(p)) FROM public.product_catalog_operations p WHERE tenant_id=t),0)+coalesce((SELECT sum(pg_column_size(p)) FROM public.product_catalog_admissions p WHERE tenant_id=t),0)>67108864 THEN RAISE EXCEPTION 'Limit pamięci katalogów' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.product_catalogs c WHERE c.tenant_id=t AND((SELECT count(*) FROM public.product_catalog_languages l WHERE(l.tenant_id,l.catalog_id)=(t,c.id))>64 OR(SELECT count(*) FROM public.product_catalog_warehouses w WHERE(w.tenant_id,w.catalog_id)=(t,c.id))>100 OR(SELECT count(*) FROM public.product_catalog_price_lists p WHERE(p.tenant_id,p.catalog_id)=(t,c.id))>100)) THEN RAISE EXCEPTION 'Limit przypisań katalogu' USING ERRCODE='23514';END IF;END $$;
-- Bootstrap all existing resources without modifying any original product column.
INSERT INTO product_catalogs(id,tenant_id,is_default,name,default_language) SELECT gen_random_uuid(),id,true,'Katalog domyślny',lower(replace(locale,'_','-')) FROM tenants;
INSERT INTO product_catalog_warehouses SELECT w.tenant_id,c.id,w.id FROM warehouses w JOIN product_catalogs c ON c.tenant_id=w.tenant_id AND c.is_default;
INSERT INTO product_catalog_price_lists SELECT p.tenant_id,c.id,p.id FROM price_lists p JOIN product_catalogs c ON c.tenant_id=p.tenant_id AND c.is_default;
INSERT INTO product_catalog_languages SELECT c.tenant_id,c.id,l.locale FROM product_catalogs c CROSS JOIN unnest(ARRAY['pl','en','de','cs','fr','it',c.default_language]) l(locale) ON CONFLICT DO NOTHING;
INSERT INTO product_catalog_languages SELECT DISTINCT p.tenant_id,c.id,p.locale FROM product_translations p JOIN product_catalogs c ON c.tenant_id=p.tenant_id AND c.is_default ON CONFLICT DO NOTHING;
ALTER TABLE products ADD COLUMN catalog_id uuid;
UPDATE products p SET catalog_id=c.id FROM product_catalogs c WHERE c.tenant_id=p.tenant_id AND c.is_default;
ALTER TABLE products ALTER COLUMN catalog_id SET NOT NULL;
ALTER TABLE products ADD CONSTRAINT product_catalog_membership_fk FOREIGN KEY(tenant_id,catalog_id) REFERENCES product_catalogs(tenant_id,id);
ALTER TABLE products ADD CONSTRAINT product_catalog_identity UNIQUE(tenant_id,catalog_id,id);
ALTER TABLE products ADD CONSTRAINT product_catalog_parent_fk FOREIGN KEY(tenant_id,catalog_id,parent_id) REFERENCES products(tenant_id,catalog_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION product_catalog_head(cid uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT h||(h->'settings') FROM (SELECT jsonb_build_object('id',c.id,'name',c.name,'active',c.active,'is_default',c.is_default,'version',c.version::text,'settings',jsonb_build_object('name',c.name,'active',c.active,'default_language',c.default_language,
 'languages',coalesce((SELECT jsonb_agg(l.locale ORDER BY l.locale) FROM public.product_catalog_languages l WHERE(l.tenant_id,l.catalog_id)=(c.tenant_id,c.id)),'[]'),
 'warehouse_ids',coalesce((SELECT jsonb_agg(w.warehouse_id ORDER BY w.warehouse_id) FROM public.product_catalog_warehouses w WHERE(w.tenant_id,w.catalog_id)=(c.tenant_id,c.id)),'[]'),
 'price_list_ids',coalesce((SELECT jsonb_agg(p.price_list_id ORDER BY p.price_list_id) FROM public.product_catalog_price_lists p WHERE(p.tenant_id,p.catalog_id)=(c.tenant_id,c.id)),'[]')),
 'product_count',(SELECT count(*) FROM public.products p WHERE(p.tenant_id,p.catalog_id)=(c.tenant_id,c.id)),'created_at',c.created_at,'updated_at',c.updated_at)
 FROM public.product_catalogs c WHERE c.tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND c.id=cid) x(h) $$;
DO $$ DECLARE t uuid;BEGIN FOR t IN SELECT id FROM tenants LOOP PERFORM public.product_catalog_budget(t);END LOOP;END $$;
CREATE FUNCTION product_catalog_settings(j jsonb) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE v jsonb;a text;n integer;
BEGIN IF jsonb_typeof(j) IS DISTINCT FROM 'object' OR(j-ARRAY['name','active','languages','default_language','warehouse_ids','price_list_ids'])<>'{}'::jsonb OR jsonb_typeof(j->'name') IS DISTINCT FROM 'string' OR length(j->>'name') NOT BETWEEN 2 AND 120 OR j->>'name' ~ '[[:cntrl:]]' OR jsonb_typeof(j->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(j->'default_language') IS DISTINCT FROM 'string' OR jsonb_typeof(j->'languages') IS DISTINCT FROM 'array' OR jsonb_typeof(j->'warehouse_ids') IS DISTINCT FROM 'array' OR jsonb_typeof(j->'price_list_ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Niepoprawne ustawienia katalogu' USING ERRCODE='23514';END IF;
 FOR a IN SELECT unnest(ARRAY['languages','warehouse_ids','price_list_ids']) LOOP n:=jsonb_array_length(j->a);IF n>(CASE a WHEN 'languages' THEN 64 ELSE 100 END) OR(n=0 AND a<>'price_list_ids') OR n<>(SELECT count(DISTINCT x) FROM jsonb_array_elements(j->a)x) THEN RAISE EXCEPTION 'Niepoprawne przypisania katalogu' USING ERRCODE='23514';END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(j->a) LOOP IF jsonb_typeof(v) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Niepoprawne przypisanie katalogu' USING ERRCODE='23514';END IF;IF a='languages' THEN IF length(v#>>'{}')>40 OR(v#>>'{}')!~'^[a-z]{2,3}(-[a-z0-9]{2,8}){0,3}$' THEN RAISE EXCEPTION 'Niepoprawny język katalogu' USING ERRCODE='23514';END IF;ELSE PERFORM(v#>>'{}')::uuid;END IF;END LOOP;END LOOP;
 IF NOT(j->'languages' ? (j->>'default_language')) THEN RAISE EXCEPTION 'Brak domyślnego języka katalogu' USING ERRCODE='23514';END IF;END $$;
CREATE FUNCTION product_catalog_frame(b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;s jsonb:=b->'settings';old_head jsonb;cid uuid;wid uuid;pid uuid;lng text;blocks jsonb:='[]';resources jsonb;
BEGIN PERFORM public.product_catalog_settings(s);IF b->>'kind' NOT IN('create','update') OR b->>'kind' IS NULL THEN RAISE EXCEPTION 'Niepoprawny podgląd katalogu' USING ERRCODE='23514';END IF;
 IF b->>'kind'='update' THEN cid:=(b->>'catalog_id')::uuid;PERFORM 1 FROM public.product_catalogs WHERE(tenant_id,id)=(t,cid) FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Brak katalogu' USING ERRCODE='P0002';END IF;old_head:=public.product_catalog_head(cid);IF old_head->>'version' IS DISTINCT FROM b->>'version' THEN RAISE EXCEPTION 'Katalog zmienił wersję' USING ERRCODE='23514';END IF;
 IF old_head->'is_default'='true'::jsonb AND s->'active'='false'::jsonb THEN blocks:=blocks||jsonb_build_array('DEFAULT_INACTIVE');END IF;END IF;
 FOR wid IN SELECT value::uuid FROM jsonb_array_elements_text(s->'warehouse_ids') ORDER BY value LOOP PERFORM 1 FROM public.warehouses WHERE(tenant_id,id)=(t,wid) FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Brak własnego magazynu' USING ERRCODE='P0002';END IF;END LOOP;
 FOR pid IN SELECT value::uuid FROM jsonb_array_elements_text(s->'price_list_ids') ORDER BY value LOOP PERFORM 1 FROM public.price_lists WHERE(tenant_id,id)=(t,pid) FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Brak własnego cennika' USING ERRCODE='P0002';END IF;END LOOP;
 IF cid IS NOT NULL THEN FOR wid IN SELECT w.warehouse_id FROM public.product_catalog_warehouses w WHERE(w.tenant_id,w.catalog_id)=(t,cid) AND NOT(s->'warehouse_ids' ? w.warehouse_id::text) ORDER BY w.warehouse_id LOOP
 IF EXISTS(SELECT 1 FROM public.stock st JOIN public.products p ON(p.tenant_id,p.id)=(st.tenant_id,st.product_id) WHERE st.tenant_id=t AND st.warehouse_id=wid AND p.catalog_id=cid AND(st.on_hand>0 OR st.reserved>0)) OR EXISTS(SELECT 1 FROM public.reservations r JOIN public.products p ON(p.tenant_id,p.id)=(r.tenant_id,r.product_id) WHERE r.tenant_id=t AND r.warehouse_id=wid AND p.catalog_id=cid AND r.state='active') THEN blocks:=blocks||jsonb_build_array('WH_STOCK:'||wid);END IF;
 IF EXISTS(SELECT 1 FROM public.wms_layer_positions x JOIN public.products p ON(p.tenant_id,p.id)=(x.tenant_id,x.product_id) WHERE x.tenant_id=t AND x.warehouse_id=wid AND p.catalog_id=cid AND(x.quantity>0 OR x.reserved>0)) THEN blocks:=blocks||jsonb_build_array('WH_WMS:'||wid);END IF;
 IF EXISTS(SELECT 1 FROM public.purchase_orders po JOIN public.purchase_order_lines l ON(l.tenant_id,l.order_id)=(po.tenant_id,po.id) JOIN public.products p ON(p.tenant_id,p.id)=(l.tenant_id,l.product_id) WHERE po.tenant_id=t AND po.warehouse_id=wid AND p.catalog_id=cid AND po.state IN('draft','ordered','partial') AND l.received_quantity+l.closed_quantity<l.quantity) THEN blocks:=blocks||jsonb_build_array('WH_OPEN_PO:'||wid);END IF;
 IF EXISTS(SELECT 1 FROM public.orders o JOIN public.order_items i ON(i.tenant_id,i.order_id)=(o.tenant_id,o.id) JOIN public.products p ON(p.tenant_id,p.id)=(i.tenant_id,i.product_id) WHERE o.tenant_id=t AND o.warehouse_id=wid AND(p.catalog_id=cid OR EXISTS(SELECT 1 FROM jsonb_array_elements(i.components) x JOIN public.products cp ON(cp.tenant_id,cp.id)=(t,(x->>'product_id')::uuid) WHERE cp.catalog_id=cid))) OR EXISTS(SELECT 1 FROM public.stock_movements m JOIN public.products p ON(p.tenant_id,p.id)=(m.tenant_id,m.product_id) WHERE m.tenant_id=t AND m.warehouse_id=wid AND p.catalog_id=cid) OR EXISTS(SELECT 1 FROM public.return_cases rc JOIN public.return_items ri ON(ri.tenant_id,ri.return_id)=(rc.tenant_id,rc.id) JOIN public.order_items roi ON(roi.tenant_id,roi.order_id,roi.id)=(ri.tenant_id,ri.order_id,ri.item_id) JOIN public.products rp ON(rp.tenant_id,rp.id)=(roi.tenant_id,roi.product_id) WHERE rc.tenant_id=t AND rc.warehouse_id=wid AND(rp.catalog_id=cid OR EXISTS(SELECT 1 FROM jsonb_array_elements(ri.components) comp JOIN public.products cp ON(cp.tenant_id,cp.id)=(t,(comp->>'product_id')::uuid) WHERE cp.catalog_id=cid))) THEN blocks:=blocks||jsonb_build_array('WH_HISTORY:'||wid);END IF;END LOOP;
 FOR pid IN SELECT p.price_list_id FROM public.product_catalog_price_lists p WHERE(p.tenant_id,p.catalog_id)=(t,cid) AND NOT(s->'price_list_ids' ? p.price_list_id::text) LOOP IF EXISTS(SELECT 1 FROM public.price_list_items i JOIN public.products p ON(p.tenant_id,p.id)=(i.tenant_id,i.product_id) WHERE i.tenant_id=t AND i.price_list_id=pid AND p.catalog_id=cid) THEN blocks:=blocks||jsonb_build_array('PRICE_DATA:'||pid);END IF;END LOOP;
 FOR lng IN SELECT l.locale FROM public.product_catalog_languages l WHERE(l.tenant_id,l.catalog_id)=(t,cid) AND NOT(s->'languages' ? l.locale) LOOP IF EXISTS(SELECT 1 FROM public.product_translations tr JOIN public.products p ON(p.tenant_id,p.id)=(tr.tenant_id,tr.product_id) WHERE tr.tenant_id=t AND tr.locale=lng AND p.catalog_id=cid) THEN blocks:=blocks||jsonb_build_array('LANGUAGE_DATA:'||lng);END IF;END LOOP;END IF;
 resources:=jsonb_build_object('warehouses',coalesce((SELECT jsonb_agg(jsonb_build_object('id',w.id,'name',w.name,'code',w.code) ORDER BY w.id) FROM public.warehouses w WHERE w.tenant_id=t AND s->'warehouse_ids' ? w.id::text),'[]'),
 'price_lists',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'currency',p.currency,'active',p.active,'version',p.version::text) ORDER BY p.id) FROM public.price_lists p WHERE p.tenant_id=t AND s->'price_list_ids' ? p.id::text),'[]'),'languages',s->'languages');
 RETURN jsonb_build_object('kind',b->>'kind','catalog_id',cid,'version',b->'version','before',old_head,'after',s,'resources',resources,'blockers',blocks,'ready',jsonb_array_length(blocks)=0);END $$;
CREATE FUNCTION product_catalog_preview_head(p public.product_catalog_previews) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT p.payload||jsonb_build_object('id',p.id,'client_key',p.client_key,'scope_hash',p.scope_hash,'created_at',p.created_at,'expires_at',p.expires_at,'operation_id',(SELECT o.id FROM public.product_catalog_operations o WHERE(o.tenant_id,o.preview_id)=(p.tenant_id,p.id))) $$;
CREATE FUNCTION product_catalog_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN RAISE EXCEPTION 'Niezmienna historia katalogów' USING ERRCODE='23514';END $$;
CREATE FUNCTION product_catalog_config_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE j jsonb:=coalesce(to_jsonb(NEW),to_jsonb(OLD));t uuid:=(j->>'tenant_id')::uuid;cid uuid;ad public.product_catalog_admissions;
BEGIN cid:=(CASE WHEN TG_TABLE_NAME='product_catalogs' THEN j->>'id' ELSE j->>'catalog_id' END)::uuid;
 IF EXISTS(SELECT 1 FROM public.product_catalog_admissions a JOIN public.product_catalog_operations o ON(o.tenant_id,o.id)=(a.tenant_id,a.operation_id) WHERE a.txid=pg_current_xact_id() AND((a.tenant_id,a.catalog_id)=((to_jsonb(NEW)->>'tenant_id')::uuid,(CASE WHEN TG_TABLE_NAME='product_catalogs' THEN to_jsonb(NEW)->>'id' ELSE to_jsonb(NEW)->>'catalog_id' END)::uuid) OR(a.tenant_id,a.catalog_id)=((to_jsonb(OLD)->>'tenant_id')::uuid,(CASE WHEN TG_TABLE_NAME='product_catalogs' THEN to_jsonb(OLD)->>'id' ELSE to_jsonb(OLD)->>'catalog_id' END)::uuid))) THEN RAISE EXCEPTION 'Konfiguracja po zapisie dowodu katalogu' USING ERRCODE='23514';END IF;
 SELECT * INTO ad FROM public.product_catalog_admissions a WHERE(a.tenant_id,a.catalog_id,a.txid)=(t,cid,pg_current_xact_id());
 IF ad.id IS NOT NULL THEN IF EXISTS(SELECT 1 FROM public.product_catalog_operations o WHERE(o.tenant_id,o.id)=(t,ad.operation_id)) THEN RAISE EXCEPTION 'Konfiguracja po zapisie dowodu katalogu' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='product_catalogs' THEN IF TG_OP='UPDATE' THEN IF(NEW.id,NEW.tenant_id,NEW.is_default,NEW.created_at) IS DISTINCT FROM(OLD.id,OLD.tenant_id,OLD.is_default,OLD.created_at) THEN RAISE EXCEPTION 'Niezmienna tożsamość katalogu' USING ERRCODE='23514';END IF;END IF;END IF;
 IF TG_OP='DELETE' AND TG_TABLE_NAME='product_catalogs' THEN RAISE EXCEPTION 'Katalog nie może zostać usunięty' USING ERRCODE='23514';END IF;
 ELSE
 -- Only trigger-owned birth/default resource enrollment; helpers are not executable by app.
 IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Konfiguracja katalogu wymaga bieżącej zgody' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='product_catalogs' THEN
  IF TG_OP='INSERT' THEN IF NOT NEW.is_default OR NOT NEW.active OR NEW.version<>1 THEN RAISE EXCEPTION 'Niepoprawny domyślny katalog' USING ERRCODE='23514';END IF;
  ELSIF TG_OP='UPDATE' THEN IF NOT OLD.is_default OR(to_jsonb(NEW)-ARRAY['version','updated_at']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['version','updated_at']) OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Niepoprawna rejestracja zasobu katalogu' USING ERRCODE='23514';END IF;
  ELSE RAISE EXCEPTION 'Niezmienny domyślny katalog' USING ERRCODE='23514';END IF;
 ELSE IF TG_OP<>'INSERT' OR NOT EXISTS(SELECT 1 FROM public.product_catalogs c WHERE(c.tenant_id,c.id)=(t,cid) AND c.is_default) THEN RAISE EXCEPTION 'Niepoprawne automatyczne przypisanie katalogu' USING ERRCODE='23514';END IF;END IF;
 END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE FUNCTION product_catalog_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE ad public.product_catalog_admissions;op public.product_catalog_operations;pr public.product_catalog_previews;h jsonb;
BEGIN IF TG_TABLE_NAME='product_catalog_admissions' THEN ad:=NEW;ELSE SELECT * INTO ad FROM public.product_catalog_admissions a WHERE(a.tenant_id,a.operation_id)=(NEW.tenant_id,NEW.id);END IF;
 IF ad.id IS NULL OR ad.txid<>pg_current_xact_id() THEN RAISE EXCEPTION 'Brak bieżącego dowodu katalogu' USING ERRCODE='23514';END IF;
 PERFORM public.product_catalog_require(ad.actor_id,ad.api_key_id,true,false);
 SELECT * INTO op FROM public.product_catalog_operations o WHERE(o.tenant_id,o.id)=(ad.tenant_id,ad.operation_id);SELECT * INTO pr FROM public.product_catalog_previews p WHERE(p.tenant_id,p.id)=(ad.tenant_id,ad.preview_id);h:=public.product_catalog_head(ad.catalog_id);
 IF op.id IS NULL OR(pr.actor_id,pr.api_key_id) IS DISTINCT FROM(ad.actor_id,ad.api_key_id) OR(op.actor_id,op.api_key_id,op.preview_id,op.catalog_id) IS DISTINCT FROM(ad.actor_id,ad.api_key_id,ad.preview_id,ad.catalog_id) OR op.payload->'after' IS DISTINCT FROM h OR h->'settings' IS DISTINCT FROM ad.payload->'after' OR op.payload->'before' IS DISTINCT FROM pr.payload->'before' OR op.payload->>'scope_hash' IS DISTINCT FROM pr.scope_hash OR op.request->'confirmed' IS DISTINCT FROM 'true'::jsonb OR op.request->>'scope_hash' IS DISTINCT FROM pr.scope_hash OR op.request_hash IS DISTINCT FROM public.product_catalog_hash(jsonb_build_object('actor',op.actor_id,'key',op.api_key_id,'preview',op.preview_id,'request',op.request)) THEN RAISE EXCEPTION 'Niezgodny pełny dowód katalogu' USING ERRCODE='23514';END IF;
 PERFORM public.product_catalog_budget(ad.tenant_id);RETURN NULL;END $$;
CREATE TRIGGER product_catalogs_guard BEFORE INSERT OR UPDATE OR DELETE ON product_catalogs FOR EACH ROW EXECUTE FUNCTION product_catalog_config_guard();
CREATE TRIGGER product_catalog_warehouses_guard BEFORE INSERT OR UPDATE OR DELETE ON product_catalog_warehouses FOR EACH ROW EXECUTE FUNCTION product_catalog_config_guard();
CREATE TRIGGER product_catalog_price_lists_guard BEFORE INSERT OR UPDATE OR DELETE ON product_catalog_price_lists FOR EACH ROW EXECUTE FUNCTION product_catalog_config_guard();
CREATE TRIGGER product_catalog_languages_guard BEFORE INSERT OR UPDATE OR DELETE ON product_catalog_languages FOR EACH ROW EXECUTE FUNCTION product_catalog_config_guard();
CREATE TRIGGER product_catalog_previews_immutable BEFORE UPDATE OR DELETE ON product_catalog_previews FOR EACH ROW EXECUTE FUNCTION product_catalog_immutable();
CREATE TRIGGER product_catalog_operations_immutable BEFORE UPDATE OR DELETE ON product_catalog_operations FOR EACH ROW EXECUTE FUNCTION product_catalog_immutable();
CREATE TRIGGER product_catalog_admissions_immutable BEFORE UPDATE OR DELETE ON product_catalog_admissions FOR EACH ROW EXECUTE FUNCTION product_catalog_immutable();
CREATE CONSTRAINT TRIGGER product_catalog_admissions_complete AFTER INSERT ON product_catalog_admissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION product_catalog_complete();
CREATE CONSTRAINT TRIGGER product_catalog_operations_complete AFTER INSERT ON product_catalog_operations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION product_catalog_complete();
CREATE FUNCTION product_catalog_bootstrap() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid;cid uuid;lng text;changed boolean:=false;
BEGIN IF TG_TABLE_NAME='tenants' THEN t:=NEW.id;lng:=lower(replace(NEW.locale,'_','-'));PERFORM pg_advisory_xact_lock(hashtextextended('catalog:'||t,0));cid:=gen_random_uuid();
 INSERT INTO public.product_catalogs(id,tenant_id,is_default,name,default_language) VALUES(cid,t,true,'Katalog domyślny',lng);
 INSERT INTO public.product_catalog_languages SELECT t,cid,l.locale FROM unnest(ARRAY['pl','en','de','cs','fr','it',lng]) l(locale) ON CONFLICT DO NOTHING;
 ELSE t:=NEW.tenant_id;PERFORM pg_advisory_xact_lock(hashtextextended('catalog:'||t,0));SELECT id INTO cid FROM public.product_catalogs WHERE tenant_id=t AND is_default FOR UPDATE;
 IF cid IS NULL THEN RAISE EXCEPTION 'Brak domyślnego katalogu' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='warehouses' THEN INSERT INTO public.product_catalog_warehouses VALUES(t,cid,NEW.id);changed:=true;
 ELSIF TG_TABLE_NAME='price_lists' THEN INSERT INTO public.product_catalog_price_lists VALUES(t,cid,NEW.id);changed:=true;END IF;
 IF changed THEN UPDATE public.product_catalogs SET version=version+1,updated_at=clock_timestamp() WHERE(tenant_id,id)=(t,cid);END IF;END IF;
 PERFORM public.product_catalog_budget(t);RETURN NEW;END $$;
CREATE TRIGGER product_catalog_tenant_birth AFTER INSERT ON tenants FOR EACH ROW EXECUTE FUNCTION product_catalog_bootstrap();
CREATE TRIGGER product_catalog_warehouse_birth AFTER INSERT ON warehouses FOR EACH ROW EXECUTE FUNCTION product_catalog_bootstrap();
CREATE TRIGGER product_catalog_price_list_birth AFTER INSERT ON price_lists FOR EACH ROW EXECUTE FUNCTION product_catalog_bootstrap();
CREATE FUNCTION product_catalog_product_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE c public.product_catalogs;
BEGIN PERFORM pg_advisory_xact_lock_shared(hashtextextended('catalog:'||NEW.tenant_id,0));IF TG_OP='UPDATE' THEN IF(NEW.tenant_id,NEW.id,NEW.catalog_id) IS DISTINCT FROM(OLD.tenant_id,OLD.id,OLD.catalog_id) THEN RAISE EXCEPTION 'Niezmienna przynależność produktu do katalogu' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 IF NEW.catalog_id IS NULL THEN SELECT id INTO NEW.catalog_id FROM public.product_catalogs WHERE tenant_id=NEW.tenant_id AND is_default;END IF;
 SELECT * INTO c FROM public.product_catalogs WHERE(tenant_id,id)=(NEW.tenant_id,NEW.catalog_id) FOR SHARE;
 IF c.id IS NULL OR NOT c.active THEN RAISE EXCEPTION 'Brak aktywnego katalogu produktu' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER product_catalog_product_membership BEFORE INSERT OR UPDATE ON products FOR EACH ROW EXECUTE FUNCTION product_catalog_product_guard();
CREATE FUNCTION product_catalog_component_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN IF EXISTS(SELECT 1 FROM public.bundle_components b JOIN public.products p ON(p.tenant_id,p.id)=(b.tenant_id,b.bundle_id) JOIN public.products q ON(q.tenant_id,q.id)=(b.tenant_id,b.product_id) WHERE(b.tenant_id,b.bundle_id,b.product_id)=(NEW.tenant_id,NEW.bundle_id,NEW.product_id) AND p.catalog_id IS DISTINCT FROM q.catalog_id) THEN RAISE EXCEPTION 'Składnik zestawu pochodzi z innego katalogu' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER product_catalog_component_membership AFTER INSERT OR UPDATE ON bundle_components DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION product_catalog_component_guard();
CREATE FUNCTION product_catalog_assignment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE c public.product_catalogs;cid uuid;changed integer:=0;
BEGIN SELECT p.catalog_id INTO cid FROM public.products p WHERE(p.tenant_id,p.id)=(NEW.tenant_id,NEW.product_id);
 IF TG_TABLE_NAME='product_translations' THEN IF EXISTS(SELECT 1 FROM public.product_catalogs dc WHERE(dc.tenant_id,dc.id)=(NEW.tenant_id,cid) AND dc.is_default) AND NOT EXISTS(SELECT 1 FROM public.product_catalog_languages l WHERE(l.tenant_id,l.catalog_id,l.locale)=(NEW.tenant_id,cid,NEW.locale)) THEN PERFORM pg_advisory_xact_lock(hashtextextended('catalog:'||NEW.tenant_id,0));ELSE PERFORM pg_advisory_xact_lock_shared(hashtextextended('catalog:'||NEW.tenant_id,0));END IF;ELSE PERFORM pg_advisory_xact_lock_shared(hashtextextended('catalog:'||NEW.tenant_id,0));END IF;IF TG_TABLE_NAME='product_translations' THEN SELECT * INTO c FROM public.product_catalogs WHERE(tenant_id,id)=(NEW.tenant_id,cid) FOR UPDATE;ELSE SELECT * INTO c FROM public.product_catalogs WHERE(tenant_id,id)=(NEW.tenant_id,cid) FOR SHARE;END IF;
 IF c.id IS NULL THEN RAISE EXCEPTION 'Brak katalogu zasobu produktu' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='stock' THEN IF NOT EXISTS(SELECT 1 FROM public.product_catalog_warehouses w WHERE(w.tenant_id,w.catalog_id,w.warehouse_id)=(NEW.tenant_id,cid,NEW.warehouse_id)) THEN RAISE EXCEPTION 'Magazyn nie jest przypisany do katalogu' USING ERRCODE='23514';END IF;
 ELSIF TG_TABLE_NAME='price_list_items' THEN IF NOT EXISTS(SELECT 1 FROM public.product_catalog_price_lists p WHERE(p.tenant_id,p.catalog_id,p.price_list_id)=(NEW.tenant_id,cid,NEW.price_list_id)) THEN RAISE EXCEPTION 'Cennik nie jest przypisany do katalogu' USING ERRCODE='23514';END IF;
 ELSE
 IF NOT EXISTS(SELECT 1 FROM public.product_catalog_languages l WHERE(l.tenant_id,l.catalog_id,l.locale)=(NEW.tenant_id,cid,NEW.locale)) THEN
  IF NOT c.is_default THEN RAISE EXCEPTION 'Język nie jest przypisany do katalogu' USING ERRCODE='23514';END IF;
  -- Existing default-catalog language workflow remains available; configuration writers use the same catalog advisory lock.
  INSERT INTO public.product_catalog_languages VALUES(NEW.tenant_id,cid,NEW.locale) ON CONFLICT DO NOTHING;GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed>0 THEN UPDATE public.product_catalogs SET version=version+1,updated_at=clock_timestamp() WHERE(tenant_id,id)=(NEW.tenant_id,cid);PERFORM public.product_catalog_budget(NEW.tenant_id);END IF;
 END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER product_catalog_stock_assignment BEFORE INSERT OR UPDATE ON stock FOR EACH ROW EXECUTE FUNCTION product_catalog_assignment_guard();
CREATE TRIGGER product_catalog_price_assignment BEFORE INSERT OR UPDATE ON price_list_items FOR EACH ROW EXECUTE FUNCTION product_catalog_assignment_guard();
CREATE TRIGGER product_catalog_translation_assignment BEFORE INSERT OR UPDATE ON product_translations FOR EACH ROW EXECUTE FUNCTION product_catalog_assignment_guard();
CREATE FUNCTION product_catalog_guards() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE tbl text;needed text[]:=ARRAY['product_catalogs','product_catalog_warehouses','product_catalog_price_lists','product_catalog_languages','product_catalog_previews','product_catalog_operations','product_catalog_admissions'];
BEGIN FOREACH tbl IN ARRAY needed LOOP IF to_regclass('public.'||tbl) IS NULL THEN RETURN false;END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM(VALUES ('product_catalogs','id'),('product_catalogs','tenant_id'),('product_catalogs','is_default'),('product_catalogs','name'),('product_catalogs','active'),('product_catalogs','default_language'),('product_catalogs','version'),('product_catalogs','created_at'),('product_catalogs','updated_at'),('product_catalog_warehouses','tenant_id'),('product_catalog_warehouses','catalog_id'),('product_catalog_warehouses','warehouse_id'),('product_catalog_price_lists','tenant_id'),('product_catalog_price_lists','catalog_id'),('product_catalog_price_lists','price_list_id'),('product_catalog_languages','tenant_id'),('product_catalog_languages','catalog_id'),('product_catalog_languages','locale'),('product_catalog_previews','id'),('product_catalog_previews','tenant_id'),('product_catalog_previews','actor_id'),('product_catalog_previews','api_key_id'),('product_catalog_previews','client_key'),('product_catalog_previews','request_hash'),('product_catalog_previews','scope_hash'),('product_catalog_previews','request'),('product_catalog_previews','payload'),('product_catalog_previews','created_at'),('product_catalog_previews','expires_at'),('product_catalog_operations','id'),('product_catalog_operations','tenant_id'),('product_catalog_operations','preview_id'),('product_catalog_operations','catalog_id'),('product_catalog_operations','actor_id'),('product_catalog_operations','api_key_id'),('product_catalog_operations','client_key'),('product_catalog_operations','request_hash'),('product_catalog_operations','request'),('product_catalog_operations','payload'),('product_catalog_operations','created_at'),('product_catalog_admissions','id'),('product_catalog_admissions','tenant_id'),('product_catalog_admissions','operation_id'),('product_catalog_admissions','preview_id'),('product_catalog_admissions','catalog_id'),('product_catalog_admissions','actor_id'),('product_catalog_admissions','api_key_id'),('product_catalog_admissions','txid'),('product_catalog_admissions','payload'),('product_catalog_admissions','created_at'))x(tbl,col) WHERE NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=to_regclass('public.'||x.tbl) AND a.attname=x.col AND NOT a.attisdropped AND(a.attnotnull OR x.col='api_key_id'))) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.products'::regclass AND attname='catalog_id' AND attnotnull AND NOT attisdropped) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_index i WHERE i.indexrelid=to_regclass('public.product_catalog_default') AND i.indrelid='public.product_catalogs'::regclass AND i.indisunique AND i.indisvalid AND i.indisready AND pg_get_expr(i.indpred,i.indrelid)='is_default') OR NOT EXISTS(SELECT 1 FROM pg_index i WHERE i.indexrelid=to_regclass('public.product_catalog_name') AND i.indrelid='public.product_catalogs'::regclass AND i.indisunique AND i.indisvalid AND i.indisready) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM pg_class WHERE oid=ANY(ARRAY(SELECT to_regclass('public.'||x) FROM unnest(needed)x)) AND(NOT relrowsecurity OR NOT relforcerowsecurity)) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['product_catalog_installed()','product_catalog_hash(jsonb)','product_catalog_access(uuid,uuid,boolean,boolean)','product_catalog_require(uuid,uuid,boolean,boolean)','product_catalog_lock()','product_catalog_budget(uuid)','product_catalog_head(uuid)','product_catalog_settings(jsonb)','product_catalog_frame(jsonb)','product_catalog_preview_head(product_catalog_previews)','product_catalog_write(uuid,uuid,text,uuid,jsonb)','product_catalog_read(uuid,uuid,text,uuid,uuid,integer,jsonb)','product_catalog_config_guard()','product_catalog_complete()','product_catalog_immutable()','product_catalog_bootstrap()','product_catalog_product_guard()','product_catalog_component_guard()','product_catalog_assignment_guard()','product_catalog_options_in_tx()','product_catalog_resolve(uuid)','product_catalog_assert_products(uuid[],uuid)','product_catalog_assert_resource(uuid,text,text)'])s(sig) WHERE to_regprocedure(sig) IS NULL) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM(VALUES ('product_catalogs_guard','product_catalogs','product_catalog_config_guard()',false),('product_catalog_warehouses_guard','product_catalog_warehouses','product_catalog_config_guard()',false),('product_catalog_price_lists_guard','product_catalog_price_lists','product_catalog_config_guard()',false),('product_catalog_languages_guard','product_catalog_languages','product_catalog_config_guard()',false),('product_catalog_previews_immutable','product_catalog_previews','product_catalog_immutable()',false),('product_catalog_operations_immutable','product_catalog_operations','product_catalog_immutable()',false),('product_catalog_admissions_immutable','product_catalog_admissions','product_catalog_immutable()',false),('product_catalog_admissions_complete','product_catalog_admissions','product_catalog_complete()',true),('product_catalog_operations_complete','product_catalog_operations','product_catalog_complete()',true),('product_catalog_tenant_birth','tenants','product_catalog_bootstrap()',false),('product_catalog_warehouse_birth','warehouses','product_catalog_bootstrap()',false),('product_catalog_price_list_birth','price_lists','product_catalog_bootstrap()',false),('product_catalog_product_membership','products','product_catalog_product_guard()',false),('product_catalog_component_membership','bundle_components','product_catalog_component_guard()',true),('product_catalog_stock_assignment','stock','product_catalog_assignment_guard()',false),('product_catalog_price_assignment','price_list_items','product_catalog_assignment_guard()',false),('product_catalog_translation_assignment','product_translations','product_catalog_assignment_guard()',false))x(name,tbl,fn,deferred) WHERE NOT EXISTS(SELECT 1 FROM pg_trigger tg WHERE tg.tgname=x.name AND tg.tgrelid=to_regclass('public.'||x.tbl) AND tg.tgenabled='O' AND NOT tg.tgisinternal AND tg.tgfoid=to_regprocedure('public.'||x.fn) AND tg.tgdeferrable=x.deferred AND tg.tginitdeferred=x.deferred)) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM(VALUES ('product_catalogs',ARRAY['tenant_id']::text[],'tenants',ARRAY['id']::text[],false),('product_catalog_warehouses',ARRAY['tenant_id','catalog_id']::text[],'product_catalogs',ARRAY['tenant_id','id']::text[],false),('product_catalog_warehouses',ARRAY['tenant_id','warehouse_id']::text[],'warehouses',ARRAY['tenant_id','id']::text[],false),('product_catalog_price_lists',ARRAY['tenant_id','catalog_id']::text[],'product_catalogs',ARRAY['tenant_id','id']::text[],false),('product_catalog_price_lists',ARRAY['tenant_id','price_list_id']::text[],'price_lists',ARRAY['tenant_id','id']::text[],false),('product_catalog_languages',ARRAY['tenant_id','catalog_id']::text[],'product_catalogs',ARRAY['tenant_id','id']::text[],false),('product_catalog_previews',ARRAY['tenant_id']::text[],'tenants',ARRAY['id']::text[],false),('product_catalog_previews',ARRAY['actor_id']::text[],'users',ARRAY['id']::text[],false),('product_catalog_previews',ARRAY['tenant_id','api_key_id']::text[],'api_keys',ARRAY['tenant_id','id']::text[],false),('product_catalog_operations',ARRAY['tenant_id']::text[],'tenants',ARRAY['id']::text[],false),('product_catalog_operations',ARRAY['actor_id']::text[],'users',ARRAY['id']::text[],false),('product_catalog_operations',ARRAY['tenant_id','api_key_id']::text[],'api_keys',ARRAY['tenant_id','id']::text[],false),('product_catalog_admissions',ARRAY['tenant_id']::text[],'tenants',ARRAY['id']::text[],false),('product_catalog_admissions',ARRAY['actor_id']::text[],'users',ARRAY['id']::text[],false),('product_catalog_admissions',ARRAY['tenant_id','api_key_id']::text[],'api_keys',ARRAY['tenant_id','id']::text[],false),('product_catalog_operations',ARRAY['tenant_id','preview_id']::text[],'product_catalog_previews',ARRAY['tenant_id','id']::text[],false),('product_catalog_operations',ARRAY['tenant_id','catalog_id']::text[],'product_catalogs',ARRAY['tenant_id','id']::text[],false),('product_catalog_admissions',ARRAY['tenant_id','operation_id']::text[],'product_catalog_operations',ARRAY['tenant_id','id']::text[],true),('product_catalog_admissions',ARRAY['tenant_id','preview_id']::text[],'product_catalog_previews',ARRAY['tenant_id','id']::text[],false),('product_catalog_admissions',ARRAY['tenant_id','catalog_id']::text[],'product_catalogs',ARRAY['tenant_id','id']::text[],true))x(tbl,cols,ref,refcols,deferred) WHERE NOT EXISTS(SELECT 1 FROM pg_constraint f WHERE f.contype='f' AND f.conrelid=to_regclass('public.'||x.tbl) AND f.confrelid=to_regclass('public.'||x.ref) AND f.convalidated AND f.condeferrable=x.deferred AND f.condeferred=x.deferred AND ARRAY(SELECT a.attname::text FROM unnest(f.conkey) WITH ORDINALITY k(attnum,ord) JOIN pg_attribute a ON a.attrelid=f.conrelid AND a.attnum=k.attnum ORDER BY k.ord)=x.cols AND ARRAY(SELECT a.attname::text FROM unnest(f.confkey) WITH ORDINALITY k(attnum,ord) JOIN pg_attribute a ON a.attrelid=f.confrelid AND a.attnum=k.attnum ORDER BY k.ord)=x.refcols)) THEN RETURN false;END IF;
 IF(SELECT count(*) FROM pg_constraint WHERE conrelid=ANY(ARRAY(SELECT to_regclass('public.'||x) FROM unnest(needed)x)) AND contype='f')<>20 THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=ANY(ARRAY(SELECT to_regclass('public.'||x) FROM unnest(needed)x)) AND contype='f' AND NOT convalidated) OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.products'::regclass AND conname='product_catalog_parent_fk' AND convalidated AND condeferrable) OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.products'::regclass AND conname='product_catalog_membership_fk' AND convalidated) THEN RETURN false;END IF;
 FOREACH tbl IN ARRAY needed LOOP IF has_table_privilege('dyna_app','public.'||tbl,'SELECT,INSERT,UPDATE,DELETE') OR has_any_column_privilege('dyna_app','public.'||tbl,'SELECT,INSERT,UPDATE') THEN RETURN false;END IF;END LOOP;
 RETURN true;END $$;
CREATE FUNCTION product_catalog_require(uid uuid,kid uuid,writing boolean,pin boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE g jsonb;BEGIN IF NOT public.product_catalog_guards() THEN RAISE EXCEPTION 'Niekompletne katalogi produktów' USING ERRCODE='55000';END IF;g:=public.product_catalog_access(uid,kid,writing,pin);
 IF g->'key_valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Klucz katalogów jest nieaktualny' USING ERRCODE='23514';END IF;IF g->'allowed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Brak aktualnego uprawnienia katalogów' USING ERRCODE='23514';END IF;RETURN g;END $$;
CREATE FUNCTION product_catalog_resolve(cid uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;c public.product_catalogs;BEGIN IF NOT public.product_catalog_guards() THEN RAISE EXCEPTION 'Niekompletne katalogi produktów' USING ERRCODE='55000';END IF;
 SELECT * INTO c FROM public.product_catalogs WHERE tenant_id=t AND((cid IS NULL AND is_default) OR id=cid) FOR SHARE;
 IF c.id IS NULL THEN RAISE EXCEPTION 'Brak katalogu' USING ERRCODE='P0002';END IF;RETURN jsonb_build_object('id',c.id,'active',c.active,'is_default',c.is_default,'version',c.version::text);END $$;
CREATE FUNCTION product_catalog_assert_products(ids uuid[],cid uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;found_id uuid;cnt integer;catalog_count integer;
BEGIN IF NOT public.product_catalog_guards() THEN RAISE EXCEPTION 'Niekompletne katalogi produktów' USING ERRCODE='55000';END IF;
 IF cardinality(ids)>10000 OR cardinality(ids) IS NULL THEN RAISE EXCEPTION 'Limit produktów katalogu' USING ERRCODE='23514';END IF;
 IF cardinality(ids)=0 THEN IF cid IS NULL THEN RETURN NULL;END IF;PERFORM public.product_catalog_resolve(cid);RETURN cid;END IF;
 SELECT count(DISTINCT p.id),count(DISTINCT p.catalog_id),(array_agg(DISTINCT p.catalog_id))[1] INTO cnt,catalog_count,found_id FROM public.products p WHERE p.tenant_id=t AND p.id=ANY(ids);
 IF cnt<>(SELECT count(DISTINCT x) FROM unnest(ids)x) THEN RAISE EXCEPTION 'Brak własnego produktu' USING ERRCODE='P0002';END IF;
 IF catalog_count<>1 OR(cid IS NOT NULL AND found_id<>cid) THEN RAISE EXCEPTION 'Produkty pochodzą z różnych katalogów' USING ERRCODE='23514';END IF;
 PERFORM public.product_catalog_resolve(found_id);RETURN found_id;END $$;
CREATE FUNCTION product_catalog_assert_resource(cid uuid,kind text,resource text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE c jsonb;t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;
BEGIN c:=public.product_catalog_resolve(cid);IF c->'active' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Katalog jest nieaktywny' USING ERRCODE='23514';END IF;
 IF kind='warehouse' THEN PERFORM 1 FROM public.warehouses WHERE(tenant_id,id)=(t,resource::uuid) FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Brak własnego magazynu' USING ERRCODE='P0002';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.product_catalog_warehouses WHERE(tenant_id,catalog_id,warehouse_id)=(t,(c->>'id')::uuid,resource::uuid)) THEN RAISE EXCEPTION 'Magazyn nie jest przypisany do katalogu' USING ERRCODE='23514';END IF;
 ELSIF kind='price_list' THEN PERFORM 1 FROM public.price_lists WHERE(tenant_id,id)=(t,resource::uuid) FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Brak własnego cennika' USING ERRCODE='P0002';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.product_catalog_price_lists WHERE(tenant_id,catalog_id,price_list_id)=(t,(c->>'id')::uuid,resource::uuid)) THEN RAISE EXCEPTION 'Cennik nie jest przypisany do katalogu' USING ERRCODE='23514';END IF;
 ELSIF kind='language' THEN IF length(resource)>40 OR resource!~'^[a-z]{2,3}(-[a-z0-9]{2,8}){0,3}$' OR resource IS NULL THEN RAISE EXCEPTION 'Niepoprawny język katalogu' USING ERRCODE='23514';END IF;IF c->'is_default'='true'::jsonb THEN RETURN;END IF;IF NOT EXISTS(SELECT 1 FROM public.product_catalog_languages WHERE(tenant_id,catalog_id,locale)=(t,(c->>'id')::uuid,resource)) THEN RAISE EXCEPTION 'Język nie jest przypisany do katalogu' USING ERRCODE='23514';END IF;
 ELSE RAISE EXCEPTION 'Nieznany rodzaj przypisania' USING ERRCODE='23514';END IF;END $$;
CREATE FUNCTION product_catalog_write(uid uuid,kid uuid,step text,pid uuid,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p public.product_catalog_previews;o public.product_catalog_operations;rh text;f jsonb;cid uuid;eid uuid;h jsonb;x text;
BEGIN PERFORM public.product_catalog_require(uid,kid,true,false);PERFORM public.product_catalog_lock();PERFORM public.product_catalog_require(uid,kid,true,false);
 IF step IS NULL OR step NOT IN('preview','commit') OR jsonb_typeof(b) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Niepoprawna operacja katalogu' USING ERRCODE='23514';END IF;
 IF step='preview' THEN
 IF b->>'kind' IS NULL OR b->>'kind' NOT IN('create','update') OR(b-(CASE WHEN b->>'kind'='create' THEN ARRAY['client_key','kind','settings'] ELSE ARRAY['client_key','kind','catalog_id','version','settings'] END))<>'{}'::jsonb THEN RAISE EXCEPTION 'Niepoprawny podgląd katalogu' USING ERRCODE='23514';END IF;
 PERFORM(b->>'client_key')::uuid;IF b->>'client_key' IS NULL THEN RAISE EXCEPTION 'Brak klucza operacji' USING ERRCODE='23514';END IF;
 rh:=public.product_catalog_hash(jsonb_build_object('actor',uid,'key',kid,'request',b));SELECT * INTO p FROM public.product_catalog_previews WHERE(tenant_id,actor_id,client_key)=(t,uid,(b->>'client_key')::uuid);
 IF p.id IS NOT NULL THEN IF p.request_hash<>rh OR p.api_key_id IS DISTINCT FROM kid THEN RAISE EXCEPTION 'Klucz podglądu ma inną treść' USING ERRCODE='23514';END IF;RETURN jsonb_build_object('preview',public.product_catalog_preview_head(p),'reused',true);END IF;
 f:=public.product_catalog_frame(b);INSERT INTO public.product_catalog_previews(id,tenant_id,actor_id,api_key_id,client_key,request_hash,scope_hash,request,payload,expires_at) VALUES(gen_random_uuid(),t,uid,kid,(b->>'client_key')::uuid,rh,public.product_catalog_hash(f),b,f,clock_timestamp()+interval '15 minutes') RETURNING * INTO p;
 PERFORM public.product_catalog_budget(t);PERFORM public.product_catalog_require(uid,kid,true,false);RETURN jsonb_build_object('preview',public.product_catalog_preview_head(p),'reused',false);
 END IF;
 IF(b-ARRAY['client_key','scope_hash','confirmed'])<>'{}'::jsonb OR b->'confirmed' IS DISTINCT FROM 'true'::jsonb OR b->>'client_key' IS NULL OR b->>'scope_hash' IS NULL THEN RAISE EXCEPTION 'Wymagana osobna zgoda katalogu' USING ERRCODE='23514';END IF;
 rh:=public.product_catalog_hash(jsonb_build_object('actor',uid,'key',kid,'preview',pid,'request',b));SELECT * INTO o FROM public.product_catalog_operations WHERE(tenant_id,actor_id,client_key)=(t,uid,(b->>'client_key')::uuid);
 IF o.id IS NOT NULL THEN IF o.request_hash<>rh OR o.api_key_id IS DISTINCT FROM kid THEN RAISE EXCEPTION 'Klucz wykonania ma inną treść' USING ERRCODE='23514';END IF;RETURN jsonb_build_object('operation',o.payload||jsonb_build_object('id',o.id,'created_at',o.created_at),'catalog',public.product_catalog_head(o.catalog_id),'reused',true);END IF;
 SELECT * INTO p FROM public.product_catalog_previews WHERE(tenant_id,id)=(t,pid) FOR UPDATE;IF p.id IS NULL THEN RAISE EXCEPTION 'Brak podglądu katalogu' USING ERRCODE='P0002';END IF;
 IF(p.actor_id,p.api_key_id) IS DISTINCT FROM(uid,kid) THEN RAISE EXCEPTION 'Podgląd należy do innego wykonawcy' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.product_catalog_operations WHERE(tenant_id,preview_id)=(t,pid)) OR p.expires_at<=clock_timestamp() OR p.scope_hash IS DISTINCT FROM b->>'scope_hash' OR p.payload->'ready' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Podgląd katalogu nie jest aktualny' USING ERRCODE='23514';END IF;
 f:=public.product_catalog_frame(p.request);IF f IS DISTINCT FROM p.payload THEN RAISE EXCEPTION 'Źródło katalogu zmieniło się' USING ERRCODE='23514';END IF;
 cid:=coalesce((f->>'catalog_id')::uuid,gen_random_uuid());eid:=gen_random_uuid();INSERT INTO public.product_catalog_admissions(id,tenant_id,operation_id,preview_id,catalog_id,actor_id,api_key_id,payload) VALUES(gen_random_uuid(),t,eid,pid,cid,uid,kid,f);
 IF f->>'kind'='create' THEN INSERT INTO public.product_catalogs(id,tenant_id,name,active,default_language) VALUES(cid,t,f->'after'->>'name',(f->'after'->>'active')::boolean,f->'after'->>'default_language');
 ELSE UPDATE public.product_catalogs SET name=f->'after'->>'name',active=(f->'after'->>'active')::boolean,default_language=f->'after'->>'default_language',version=version+1,updated_at=clock_timestamp() WHERE(tenant_id,id)=(t,cid);
 DELETE FROM public.product_catalog_warehouses WHERE(tenant_id,catalog_id)=(t,cid);DELETE FROM public.product_catalog_price_lists WHERE(tenant_id,catalog_id)=(t,cid);DELETE FROM public.product_catalog_languages WHERE(tenant_id,catalog_id)=(t,cid);END IF;
 INSERT INTO public.product_catalog_warehouses SELECT t,cid,value::uuid FROM jsonb_array_elements_text(f->'after'->'warehouse_ids');INSERT INTO public.product_catalog_price_lists SELECT t,cid,value::uuid FROM jsonb_array_elements_text(f->'after'->'price_list_ids');INSERT INTO public.product_catalog_languages SELECT t,cid,value FROM jsonb_array_elements_text(f->'after'->'languages');
 h:=public.product_catalog_head(cid);INSERT INTO public.product_catalog_operations(id,tenant_id,preview_id,catalog_id,actor_id,api_key_id,client_key,request_hash,request,payload) VALUES(eid,t,pid,cid,uid,kid,(b->>'client_key')::uuid,rh,b,jsonb_build_object('preview_id',pid,'catalog_id',cid,'kind',f->>'kind','client_key',b->>'client_key','scope_hash',p.scope_hash,'request',b,'before',f->'before','after',h)) RETURNING * INTO o;
 PERFORM public.product_catalog_budget(t);PERFORM public.product_catalog_require(uid,kid,true,false);RETURN jsonb_build_object('operation',o.payload||jsonb_build_object('id',o.id,'created_at',o.created_at),'catalog',h,'reused',false);END $$;
CREATE FUNCTION product_catalog_read(uid uuid,kid uuid,step text,rid uuid,cursor_id uuid,lim integer,q jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;preview_row public.product_catalog_previews;operation_row public.product_catalog_operations;j jsonb;data jsonb;nextid uuid;
BEGIN PERFORM public.product_catalog_require(uid,kid,false,false);IF step IS NULL OR step NOT IN('options','list','detail','preview','operation','history') OR lim IS NULL OR lim NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Niepoprawny odczyt katalogów' USING ERRCODE='23514';END IF;
 IF step='detail' THEN j:=public.product_catalog_head(rid);IF j IS NULL THEN RAISE EXCEPTION 'Brak katalogu' USING ERRCODE='P0002';END IF;RETURN jsonb_build_object('catalog',j);
 ELSIF step='preview' THEN SELECT * INTO preview_row FROM public.product_catalog_previews WHERE(tenant_id,id)=(t,rid);IF preview_row.id IS NULL THEN RAISE EXCEPTION 'Brak podglądu katalogu' USING ERRCODE='P0002';END IF;RETURN jsonb_build_object('preview',public.product_catalog_preview_head(preview_row));
 ELSIF step='operation' THEN SELECT * INTO operation_row FROM public.product_catalog_operations WHERE(tenant_id,id)=(t,rid);IF operation_row.id IS NULL THEN RAISE EXCEPTION 'Brak wykonania katalogu' USING ERRCODE='P0002';END IF;RETURN jsonb_build_object('operation',operation_row.payload||jsonb_build_object('id',operation_row.id,'created_at',operation_row.created_at));
 ELSIF step='options' THEN
 IF(SELECT count(*) FROM public.warehouses WHERE tenant_id=t)>100 OR(SELECT count(*) FROM public.price_lists WHERE tenant_id=t)>100 THEN RAISE EXCEPTION 'Limit zasobów katalogów' USING ERRCODE='23514';END IF;
 RETURN jsonb_build_object('catalogs',coalesce((SELECT jsonb_agg(public.product_catalog_head(c.id) ORDER BY c.id) FROM public.product_catalogs c WHERE tenant_id=t),'[]'),
 'warehouses',coalesce((SELECT jsonb_agg(jsonb_build_object('id',w.id,'name',w.name,'code',w.code) ORDER BY w.id) FROM public.warehouses w WHERE tenant_id=t),'[]'),
 'price_lists',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'currency',p.currency,'active',p.active,'version',p.version::text) ORDER BY p.id) FROM public.price_lists p WHERE tenant_id=t),'[]'),
 'languages',coalesce((SELECT jsonb_agg(x.locale ORDER BY x.locale) FROM(SELECT DISTINCT locale FROM public.product_catalog_languages WHERE tenant_id=t)x),'[]'));
 ELSIF step='list' THEN SELECT coalesce(jsonb_agg(public.product_catalog_head(x.id) ORDER BY x.id),'[]') INTO data FROM(SELECT id FROM public.product_catalogs WHERE tenant_id=t AND(cursor_id IS NULL OR id>cursor_id) ORDER BY id LIMIT lim)x;
 IF jsonb_array_length(data)=lim THEN nextid:=(data->-1->>'id')::uuid;IF NOT EXISTS(SELECT 1 FROM public.product_catalogs WHERE tenant_id=t AND id>nextid) THEN nextid:=NULL;END IF;END IF;
 ELSE IF q->>'kind'='preview' THEN SELECT coalesce(jsonb_agg(x.head ORDER BY x.id),'[]') INTO data FROM(SELECT p.id,jsonb_build_object('id',p.id,'kind','preview','catalog_id',p.payload->'catalog_id','scope_hash',p.scope_hash,'name',p.payload->'after'->>'name','created_at',p.created_at,'expires_at',p.expires_at,'operation_id',(SELECT id FROM public.product_catalog_operations o WHERE(o.tenant_id,o.preview_id)=(t,p.id))) head FROM public.product_catalog_previews p WHERE tenant_id=t AND(cursor_id IS NULL OR id>cursor_id) ORDER BY id LIMIT lim)x;
 IF jsonb_array_length(data)=lim THEN nextid:=(data->-1->>'id')::uuid;IF NOT EXISTS(SELECT 1 FROM public.product_catalog_previews WHERE tenant_id=t AND id>nextid) THEN nextid:=NULL;END IF;END IF;
 ELSIF q->>'kind'='operation' THEN SELECT coalesce(jsonb_agg(x.head ORDER BY x.id),'[]') INTO data FROM(SELECT o.id,jsonb_build_object('id',o.id,'kind','operation','catalog_id',o.catalog_id,'scope_hash',o.payload->>'scope_hash','name',o.payload->'after'->>'name','created_at',o.created_at,'preview_id',o.preview_id) head FROM public.product_catalog_operations o WHERE tenant_id=t AND(cursor_id IS NULL OR id>cursor_id) ORDER BY id LIMIT lim)x;
 IF jsonb_array_length(data)=lim THEN nextid:=(data->-1->>'id')::uuid;IF NOT EXISTS(SELECT 1 FROM public.product_catalog_operations WHERE tenant_id=t AND id>nextid) THEN nextid:=NULL;END IF;END IF;
 ELSE RAISE EXCEPTION 'Niepoprawny rodzaj historii' USING ERRCODE='23514';END IF;END IF;
 RETURN jsonb_build_object('data',data,'next_cursor',nextid);END $$;
CREATE FUNCTION product_catalog_options_in_tx() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;
BEGIN IF NOT public.product_catalog_guards() THEN RAISE EXCEPTION 'Niekompletne katalogi produktów' USING ERRCODE='55000';END IF;
 IF(SELECT count(*) FROM public.product_catalogs WHERE tenant_id=t)>100 OR(SELECT count(*) FROM public.warehouses WHERE tenant_id=t)>100 OR(SELECT count(*) FROM public.price_lists WHERE tenant_id=t)>100 THEN RAISE EXCEPTION 'Limit zasobów katalogów' USING ERRCODE='23514';END IF;
 RETURN jsonb_build_object('catalogs',coalesce((SELECT jsonb_agg(public.product_catalog_head(c.id) ORDER BY c.id) FROM public.product_catalogs c WHERE tenant_id=t),'[]'),'warehouses',coalesce((SELECT jsonb_agg(jsonb_build_object('id',w.id,'name',w.name,'code',w.code) ORDER BY w.id) FROM public.warehouses w WHERE tenant_id=t),'[]'),'price_lists',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'currency',p.currency,'active',p.active,'version',p.version::text) ORDER BY p.id) FROM public.price_lists p WHERE tenant_id=t),'[]'),'languages',coalesce((SELECT jsonb_agg(x.locale ORDER BY x.locale) FROM(SELECT DISTINCT locale FROM public.product_catalog_languages WHERE tenant_id=t)x),'[]'));END $$;
-- Public helpers are typed; raw supplied principal remains the documented trusted-app boundary.
DO $$ DECLARE f record;BEGIN FOR f IN SELECT oid::regprocedure sig FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'product_catalog_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,dyna_app',f.sig);END LOOP;END $$;
GRANT EXECUTE ON FUNCTION product_catalog_installed(),product_catalog_guards(),product_catalog_access(uuid,uuid,boolean,boolean),product_catalog_require(uuid,uuid,boolean,boolean),product_catalog_read(uuid,uuid,text,uuid,uuid,integer,jsonb),product_catalog_write(uuid,uuid,text,uuid,jsonb),product_catalog_options_in_tx(),product_catalog_resolve(uuid),product_catalog_assert_products(uuid[],uuid),product_catalog_assert_resource(uuid,text,text) TO dyna_app;
